@enter_exit_debug_logging
def connect_to(hops, ru_service, ru_name=None, fh_interface=None, local_server_port=None):
    """
    connect to a ru via ssh from hops

    :param hops: List[SSHHop], VM/PC/Container supporting/to support the SSHD service for hop to RU,
    item in list can be instance of SSHHop/ExtraSSHServiceHop/LXCSSHHop.
    :param ru_service: RUService, ru ssh connection configuration, password is required if ru_name param is None
    :param ru_name: Optional[str], ru name, None by default
    :param fh_interface: Optional[str], cpri or ecpri, None by default
    :param local_server_port: Optional[int], None by default, port listened by local server serving the portforwarding,
    if None, will select an idle port in range [50000, 65535]
    :return: RFSWSSHConnection
    """
    rfsw_connection = RFSWSSHConnection(hops,
                                        ru_service,
                                        ru_name=ru_name,
                                        fh_interface=fh_interface,
                                        local_server_port=local_server_port)
    rfsw_connection.setup()
    return rfsw_connection


def fetch_managed_rus():
    return supported_rus()


def lookup_managed_ru_accounts(ru_name, fh_interface=None):
    accounts = lookup_accounts(ru_name, fh_interface)
    return [AccountInfomation(account.platform, account.username, account.fh_interface) for account in accounts]


class SSHHop(object):

    @classmethod
    def create(cls, **parameters):
        host = parameters['host']
        username = parameters['username']
        password = parameters.get('password')
        port = parameters.get('port', 22)
        connecting_timeout = parameters.get('connecting_timeout', 10)
        signature = cls.generate_signature(parameters)
        return SSHHop(host,
                      username,
                      password=password,
                      port=port,
                      connecting_timeout=connecting_timeout,
                      signature=signature)

    @classmethod
    def generate_signature(cls, obj):
        if isinstance(obj, dict):
            keys = list(obj.keys())
            keys.sort()
            obj = {key: obj[key] for key in keys}
        return str(obj)

    def __init__(self, host, username, password=None, port=22, connecting_timeout=10, signature=None):
        self.host = host
        self.username = username
        self.password = password
        self.port = port
        self.connecting_timeout = connecting_timeout
        self.signature = signature or self.generate_signature(self)

    def __str__(self):
        return str({'host': self.host,
                    'username': self.username,
                    'password': self.password,
                    'port': self.port,
                    'connecting_timeout': self.connecting_timeout})


class ExtraSSHServiceHop(SSHHop):

    @classmethod
    def create(cls, **parameters):
        host = parameters['host']
        username = parameters['username']
        password = parameters.get('password')
        port = parameters.get('port', 22)
        connecting_timeout = parameters.get('connecting_timeout', 10)
        new_port = parameters['new_port']
        sudo_enabled = parameters.get('sudo_enabled', True)
        signature = cls.generate_signature(parameters)
        return ExtraSSHServiceHop(host,
                                  username,
                                  new_port,
                                  password=password,
                                  port=port,
                                  sudo_enabled=sudo_enabled,
                                  connecting_timeout=connecting_timeout,
                                  signature=signature)

    def __init__(self,
                 host,
                 username,
                 new_port,
                 password=None,
                 port=22,
                 sudo_enabled=False,
                 connecting_timeout=10,
                 signature=None):
        self.new_port = new_port
        self.sudo_enabled = sudo_enabled
        super(ExtraSSHServiceHop, self).__init__(host, username, password, port, connecting_timeout, signature)

    def __str__(self):
        return str({'host': self.host,
                    'username': self.username,
                    'password': self.password,
                    'port': self.port,
                    'new_port': self.new_port,
                    'sudo_enabled': self.sudo_enabled,
                    'connecting_timeout': self.connecting_timeout})


class LXCSSHHop(SSHHop):
    @classmethod
    def create(cls, **parameters):
        host_hop = parameters['host_hop']
        container_id = parameters['container_id']
        host = parameters['host']
        username = parameters['username']
        password = parameters.get('password')
        port = parameters.get('port', 22)
        connecting_timeout = parameters.get('connecting_timeout', 10)
        sudo_enabled = parameters.get('sudo_enabled', False)
        signature = cls.generate_signature(parameters)
        return LXCSSHHop(host_hop,
                         container_id,
                         host,
                         username,
                         password,
                         port=port,
                         sudo_enabled=sudo_enabled,
                         connecting_timeout=connecting_timeout,
                         signature=signature)

    def __init__(self,
                 host_hop,
                 container_id,
                 host,
                 username,
                 password,
                 port=22,
                 sudo_enabled=False,
                 connecting_timeout=10,
                 signature=None):
        self.host_hop = host_hop
        self.container_id = container_id
        self.sudo_enabled = sudo_enabled
        super(LXCSSHHop, self).__init__(host, username, password, port, connecting_timeout, signature)

    def __str__(self):
        return str({'host_hop': str(self.host_hop),
                    'container_id': self.container_id,
                    'host': self.host,
                    'username': self.username,
                    'password': self.password,
                    'port': self.port,
                    'sudo_enabled': self.sudo_enabled,
                    'connecting_timeout': self.connecting_timeout})


class RUService(object):
    @classmethod
    def create(cls, **parameters):
        host = parameters['host']
        username = parameters['username']
        password = parameters.get('password')
        port = parameters.get('port', 22)
        connecting_timeout = parameters.get('connecting_timeout', 10)
        return RUService(host, username, password, port, connecting_timeout=connecting_timeout)

    def __init__(self, host, username, password=None, port=22, connecting_timeout=10):
        self.host = host
        self.username = username
        self.password = password
        self.port = port
        self.connecting_timeout = connecting_timeout

    def __str__(self):
        return str({'host': self.host,
                    'username': self.username,
                    'password': self.password,
                    'port': self.port,
                    'connecting_timeout': self.connecting_timeout})


class RFSWSSHConnection(ManagedObject):

    def __init__(self, hops, ru_service, ru_name=None, fh_interface=None, local_server_port=None):
        super(RFSWSSHConnection, self).__init__()
        self._hops = hops
        self._ru_service = ru_service
        self._ru_name = ru_name
        self._fh_interface = fh_interface
        self._local_server_port = local_server_port

        self._branch = None
        self._client = None
        self._additional_connection = []

    def _setup(self):
        account = self._create_ru_account(username=self._ru_service.username,
                                          password=self._ru_service.password,
                                          ru_name=self._ru_name,
                                          fh_interface=self._fh_interface)

        local_server_port = self._local_server_port or self._select_idle_port()
        logging.debug('local server port for portforwarding is {}'.format(local_server_port))
        portforwarding = Portforwarding()
        self._branch = self._create_branch(portforwarding, self._hops, self._ru_service, local_server_port)
        exception_raised = False
        try:
            self._branch.setup()
            self._client = self._create_client(username=account.username,
                                               password=account.password,
                                               port=local_server_port)
        except paramiko.ssh_exception.AuthenticationException as exp:
            if sys.version_info.major == 2:
                logging.error("traceback: \r\n{}".format(traceback.format_exc()))
            exception_raised = True
            raise_from(
                ConnectionFail("unable to connect to {}:{} for authentication failure".
                               format(self._ru_service.host, self._ru_service.port)),
                exp)
        except (paramiko.ssh_exception.SSHException, socket.error) as exp:
            if sys.version_info.major == 2:
                logging.error("traceback: \r\n{}".format(traceback.format_exc()))
            exception_raised = True
            raise_from(
                ConnectionFail("unable to connect client to {}:{}".
                               format(self._ru_service.host, self._ru_service.port)),
                exp)
        finally:
            if exception_raised:
                self._teardown()

    def _teardown(self):
        try:
            if self._client:
                self._client.close()
                self._client = None
        finally:
            if self._branch:
                self._branch.teardown()
                self._branch = None

    @enter_exit_debug_logging
    def create_additional_connection(self, ru_username, ru_password=None):
        new_hops = []
        for hop in self._hops:
            if type(hop) is SSHHop:
                new_hops.append(hop)
            elif type(hop) is ExtraSSHServiceHop:
                new_hops.append(SSHHop(hop.host, hop.username, hop.password, port=hop.new_port))
            elif type(hop) is LXCSSHHop:
                new_hops.append(SSHHop(hop.host, hop.username, hop.password, port=hop.port))
            else:
                raise HopTypeNotSupported("hop type {} is not supported".format(type(hop)))

        new_service = RUService(
            self._ru_service.host,
            ru_username,
            ru_password,
            self._ru_service.port,
            self._ru_service.connecting_timeout)

        new_connection = RFSWSSHConnection(new_hops, new_service, self._ru_name, self._fh_interface)
        self.add_prerequisite(new_connection)
        return new_connection

    def disconnect(self):
        self.teardown()

    """
    below public methods are to simulate the same protocol as SSHConnection of taf.transport.ssh
    """
    def invoke_shell(self):
        return self._client.invoke_shell()

    @enter_exit_debug_logging
    def execute(self, command, timeout=None):
        _, _stdout, _stderr = self._client.exec_command(command, get_pty=True, timeout=timeout)
        return _stdout.read() + _stderr.read()

    @enter_exit_debug_logging
    def send_command(self, command, bufsize=-1, timeout=None, get_pty=False):
        return self._client.exec_command(command, bufsize=bufsize, timeout=timeout, get_pty=get_pty)

    """
    above public methods are to expose same protocol as SSHConnection of taf.transport.ssh
    """

    @classmethod
    def _create_ru_account(cls, username=None, password=None, ru_name=None, fh_interface=None):
        if not username:
            raise CredentialRelatedInfoInsufficient("username for ru is not specified")

        if not (ru_name or password):
            raise CredentialRelatedInfoInsufficient("either ru name or password is needed for user {}".format(username))

        if password:
            account = AccountSecurityInformation(ru_name, username, password, fh_interface)
        else:  # ru_name
            account = lookup_account(ru_name, username, fh_interface=fh_interface)

            if not account:
                raise CredentialRelatedInfoInvalid("No credential for ru {} with name {}".format(ru_name, ru_name))
        return account

    @classmethod
    def _create_branch(cls, portforwarding, hops, ru_service, forwarding_port):
        operatable_hops = []
        hop_config_vs_hop_instance = {}
        for hop in hops:
            if type(hop) is SSHHop:
                hop_obj = portforwarding.create_ssh_forwardable_hop(host=hop.host,
                                                                    user=hop.username,
                                                                    password=hop.password,
                                                                    port=hop.port)

                operatable_hops.append(hop_obj)
                hop_config_vs_hop_instance[hop.signature] = hop_obj
            elif type(hop) is ExtraSSHServiceHop:

                hop_obj = portforwarding.create_extra_sshd_forwardable_hop(
                    new_sshd_port=hop.new_port,
                    host=hop.host,
                    user=hop.username,
                    password=hop.password,
                    port=hop.port,
                    sudo_prefix="sudo " if hop.sudo_enabled else "",
                    timeout=hop.connecting_timeout)
                operatable_hops.append(hop_obj)
                hop_config_vs_hop_instance[hop.signature] = hop_obj
            elif type(hop) is LXCSSHHop:
                host_hop_obj = hop_config_vs_hop_instance[hop.generate_signature(hop.host_hop)]
                operatable_hops.append(portforwarding.create_lxc_sshd_forwardable_hop(
                    host_hop_obj,
                    hop.container_id,
                    hop.host,
                    user=hop.username,
                    password=hop.password,
                    port=hop.port,
                    sudo_prefix="sudo " if hop.sudo_enabled else "",
                    timeout=hop.connecting_timeout))

        remote_service = portforwarding.create_remote_service(ip=ru_service.host, port=ru_service.port)

        return portforwarding.create_ssh_forwarding_branch(hops=operatable_hops,
                                                           forwarding_port=forwarding_port,
                                                           remote_service=remote_service)

    @classmethod
    def _select_idle_port(cls):
        user_ports = set(range(50000, 65535))
        local_listening_ports = set([int(connection.laddr.port) for connection in psutil.net_connections()])
        selectable_ports = user_ports - local_listening_ports
        random_index = random.randint(0, len(selectable_ports))
        return list(selectable_ports)[random_index]

    @classmethod
    def _create_client(cls, username, password, port):
        logging.debug('connecting to local port {}'.format(port))

        client = paramiko.SSHClient()
        client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        client.connect(
            hostname="127.0.0.1",
            username=username,
            password=password,
            port=port,
            look_for_keys=False
        )

        return client
